import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"8、【比】 坤下坎上","description":"橫渠易說 - 8、【比】 坤下坎上","frontmatter":{"title":"8、【比】 坤下坎上","description":"橫渠易說 - 8、【比】 坤下坎上"},"headers":[],"relativePath":"classics/hengqu/010.md","filePath":"classics/hengqu/010.md"}'),l={name:"classics/hengqu/010.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_8、【比】-坤下坎上" tabindex="-1">8、【比】 坤下坎上 <a class="header-anchor" href="#_8、【比】-坤下坎上" aria-label="Permalink to “8、【比】 坤下坎上”">​</a></h1><h3 id="彖曰-比吉-也-比-輔也-下順從也。-原筮元永貞無咎-以剛中也。-不寧方來-上下應也。-後夫兇-其道窮也。" tabindex="-1">彖曰：“比吉”也，比，輔也，下順從也。“原筮元永貞無咎”，以剛中也。“不寧方來”，上下應也。“後夫兇”，其道窮也。 <a class="header-anchor" href="#彖曰-比吉-也-比-輔也-下順從也。-原筮元永貞無咎-以剛中也。-不寧方來-上下應也。-後夫兇-其道窮也。" aria-label="Permalink to “彖曰：“比吉”也，比，輔也，下順從也。“原筮元永貞無咎”，以剛中也。“不寧方來”，上下應也。“後夫兇”，其道窮也。”">​</a></h3><h3 id="象曰-地上有水-比-先王以建萬國-親諸侯。" tabindex="-1">象曰：地上有水，比，先王以建萬國，親諸侯。 <a class="header-anchor" href="#象曰-地上有水-比-先王以建萬國-親諸侯。" aria-label="Permalink to “象曰：地上有水，比，先王以建萬國，親諸侯。”">​</a></h3><p>必原筮者，慎所與也。</p><h3 id="初六-有孚比之-無咎。有孚盈缶-終來有它-吉。-象曰-比之初六-有它吉也。" tabindex="-1">初六，有孚比之，無咎。有孚盈缶，終來有它，吉。 象曰：比之初六，有它吉也。 <a class="header-anchor" href="#初六-有孚比之-無咎。有孚盈缶-終來有它-吉。-象曰-比之初六-有它吉也。" aria-label="Permalink to “初六，有孚比之，無咎。有孚盈缶，終來有它，吉。 象曰：比之初六，有它吉也。”">​</a></h3><p>柔而無應，能擇有信者親之，己之誠素著顯，終有它吉，比好先也。</p><h3 id="六二-比之自內-貞吉。-象曰-比之自內-不自失也。" tabindex="-1">六二，比之自內，貞吉。 象曰：“比之自內”，不自失也。 <a class="header-anchor" href="#六二-比之自內-貞吉。-象曰-比之自內-不自失也。" aria-label="Permalink to “六二，比之自內，貞吉。 象曰：“比之自內”，不自失也。”">​</a></h3><p>愛自親始，人道之正，故曰“貞吉”。</p><h3 id="六三-比之匪人。-象曰-比之匪人-不亦傷乎" tabindex="-1">六三，比之匪人。 象曰：“比之匪人”，不亦傷乎! <a class="header-anchor" href="#六三-比之匪人。-象曰-比之匪人-不亦傷乎" aria-label="Permalink to “六三，比之匪人。 象曰：“比之匪人”，不亦傷乎!”">​</a></h3><p>履非其正，比之必匪其人，故可傷。</p><h3 id="六四-外比之-貞吉。-象曰-外比於賢-以從上也。" tabindex="-1">六四，外比之，貞吉。 象曰：外比於賢，以從上也。 <a class="header-anchor" href="#六四-外比之-貞吉。-象曰-外比於賢-以從上也。" aria-label="Permalink to “六四，外比之，貞吉。 象曰：外比於賢，以從上也。”">​</a></h3><h3 id="九五-顯比-王用三驅失前禽-邑人不誡-吉。-象曰-顯比之吉-位正中也。舍逆取順-失前禽也。-邑人不誡-上使中也。" tabindex="-1">九五，顯比，王用三驅失前禽，邑人不誡，吉。 象曰：顯比之吉，位正中也。舍逆取順，失前禽也。“邑人不誡”，上使中也。 <a class="header-anchor" href="#九五-顯比-王用三驅失前禽-邑人不誡-吉。-象曰-顯比之吉-位正中也。舍逆取順-失前禽也。-邑人不誡-上使中也。" aria-label="Permalink to “九五，顯比，王用三驅失前禽，邑人不誡，吉。 象曰：顯比之吉，位正中也。舍逆取順，失前禽也。“邑人不誡”，上使中也。”">​</a></h3><h3 id="上六-比之無首-兇。-象曰-比之無首-無所終也。" tabindex="-1">上六，比之無首，兇。 象曰：“比之無首”，無所終也。 <a class="header-anchor" href="#上六-比之無首-兇。-象曰-比之無首-無所終也。" aria-label="Permalink to “上六，比之無首，兇。 象曰：“比之無首”，無所終也。”">​</a></h3><p>失前禽，謂三面而驅，意在緩逸之，不務殺也。順奔然後取之，故被傷者少也。 以剛居中而顯明比道，伐止有罪，不為濫刑，故邑人不誡，為上用中，此之謂也。不比者不懲，非用中也，故比必顯之，然殺不可務也。一雲：上使中者，付得其人也。</p>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
